// Auto-generated by the Nexen pipeline — deterministic auth contract.
// Pages import { AuthProvider, useAuth } from '@/lib/auth'. In mock-mode
// preview, useAuth() returns a seeded logged-in demo user and never throws, so
// auth-gated pages render without a real login. /strip-mocks collapses the mock
// branch at finalize. DO NOT hand-edit or define your own AuthContext/useAuth.
'use client';
// NOTE: this is a `.ts` file (the canonical auth path across all stack plans),
// so it uses `createElement` instead of JSX.
import {
  createContext,
  createElement,
  useContext,
  useEffect,
  useState,
  useCallback,
  type ReactNode,
} from 'react';

// Next.js inlines the EXACT text `process.env.NEXT_PUBLIC_MOCK_MODE` into the
// browser bundle. A computed or optional-chained lookup is never inlined: the
// server read 'true', the browser `undefined`, so the two first renders
// differed (a hydration error on every screen) and the browser believed nobody
// was signed in. `typeof process` keeps Vite, which has no `process`, safe.
const __NEXEN_IS_MOCK__ =
  (typeof process !== 'undefined' && process.env.NEXT_PUBLIC_MOCK_MODE === 'true') ||
  (typeof import.meta !== 'undefined' &&
    (import.meta as unknown as { env?: Record<string, string> }).env?.VITE_MOCK_MODE === 'true');

// Inline token storage using the SAME key the typed API client uses
// ('auth_token'), so a real-mode login via useAuth().login() is visible to
// @/lib/api. Inlined (not imported from @/lib/authToken) so this module has no
// cross-file dependency — @/lib/authToken is only emitted for sidecar backends.
const __NEXEN_TOKEN_KEY__ = 'auth_token';
function __nexenGetToken(): string | null {
  if (typeof window === 'undefined') return null;
  try { return window.localStorage.getItem(__NEXEN_TOKEN_KEY__); } catch { return null; }
}
function __nexenSetToken(t: string): void {
  if (typeof window === 'undefined') return;
  try { window.localStorage.setItem(__NEXEN_TOKEN_KEY__, t); } catch { /* ignore */ }
}
function __nexenClearToken(): void {
  if (typeof window === 'undefined') return;
  try { window.localStorage.removeItem(__NEXEN_TOKEN_KEY__); } catch { /* ignore */ }
}

export interface AuthUser {
  id: string;
  email: string;
  name: string;
  role: string;
}

export interface AuthState {
  user: AuthUser | null;
  token: string | null;
  isAuthenticated: boolean;
  loading: boolean;
  login: (token: string, user?: AuthUser | null) => void;
  logout: () => void;
  /** Re-read the signed-in user from the server (after a profile or role change). */
  refresh: () => Promise<void>;
}

const DEMO_USER: AuthUser = { id: "00000000-0000-4000-8000-000000000001", email: "demo@example.com", name: "Demo User", role: "admin" };

// Frozen mock session used both as the context default (so useAuth works with no
// provider) and the provider's initial state in mock mode.
const MOCK_SESSION: AuthState = {
  user: DEMO_USER,
  token: 'nexen-mock-token',
  isAuthenticated: true,
  loading: false,
  login: () => {},
  logout: () => {},
  refresh: async () => {},
};

const AuthContext = createContext<AuthState | null>(
  __NEXEN_IS_MOCK__ ? MOCK_SESSION : null,
);

/** The signed-in user as the server reports it (`GET /api/auth/me`), or null
 *  when the server says there is no session (401). Any other answer — a network
 *  error, a 404 on an app without that route — is "unknown": keep what we have. */
async function __nexenFetchMe(token: string | null): Promise<AuthUser | null | undefined> {
  try {
    const res = await fetch('/api/auth/me', {
      credentials: 'include',
      headers: token ? { Authorization: `Bearer ${token}` } : {},
    });
    if (res.status === 401) return null;
    if (!res.ok) return undefined;
    const body = (await res.json().catch(() => null)) as Record<string, unknown> | null;
    const u = (body && ((body.user as Record<string, unknown>) ?? body)) as Record<string, unknown> | null;
    if (!u || typeof u !== 'object' || !u.id) return undefined;
    return {
      id: String(u.id),
      email: String(u.email ?? ''),
      name: String(u.name ?? u.fullName ?? u.full_name ?? ''),
      role: String(u.role ?? ''),
    };
  } catch {
    return undefined;
  }
}

// A signed-out visitor on a page that needs a session is sent to sign in. Pages
// carry no "signed-in only" flag, so the page's own API answering 401 is the
// signal, confirmed with `/api/auth/me` first: a 401 a signed-in person gets for
// something else never sends them away. Published apps showed the raw
// {"error":"Unauthorized"} instead (2026-11-04); mock mode never gets here.
const __NEXEN_LOGIN_ROUTE__ = "/login";
const __NEXEN_AUTH_PAGES__ = /^\/(log-?in|sign-?in|sign-?up|register|forgot-password|reset-password)(\/|$)/i;
let __nexenGuarded = false;
function __nexenGuardSignedOut(): void {
  if (__nexenGuarded || typeof window === 'undefined') return;
  __nexenGuarded = true;
  const base = window.fetch.bind(window);
  let checking = false;
  window.fetch = async (input: RequestInfo | URL, init?: RequestInit): Promise<Response> => {
    const res = await base(input, init);
    if (res.status !== 401 || checking) return res;
    const here = window.location;
    let url: URL;
    try { url = new URL(input instanceof Request ? input.url : String(input), here.href); } catch { return res; }
    if (url.origin !== here.origin || !url.pathname.startsWith('/api/') || url.pathname.startsWith('/api/auth/')
        || here.pathname === __NEXEN_LOGIN_ROUTE__ || __NEXEN_AUTH_PAGES__.test(here.pathname)) return res;
    checking = true;
    void __nexenFetchMe(__nexenGetToken()).then((me) => {
      checking = false;
      if (me === null) here.replace(`${__NEXEN_LOGIN_ROUTE__}?next=${encodeURIComponent(here.pathname + here.search)}`);
    });
    return res;
  };
}

/** `initialUser` is who the SERVER says is signed in (the root layout reads the
 *  session cookie and passes it). Starting from it — and never from
 *  localStorage — makes the first browser render identical to the server's: the
 *  provider used to read the stored token while rendering, so every page that
 *  showed sign-in state failed hydration (React #418), and after a reload the
 *  user was gone (navbar back to "Sign in", role links missing) because nothing
 *  ever re-read it. Browser storage is read after mount, in an effect. */
export function AuthProvider({ children, initialUser }: { children: ReactNode; initialUser?: AuthUser | null }) {
  const [user, setUser] = useState<AuthUser | null>(
    __NEXEN_IS_MOCK__ ? DEMO_USER : (initialUser ?? null),
  );
  const [token, setTok] = useState<string | null>(__NEXEN_IS_MOCK__ ? 'nexen-mock-token' : null);
  // Known on the first render when the server passed a user; otherwise not until
  // the effect below has asked the server.
  const [loading, setLoading] = useState<boolean>(!__NEXEN_IS_MOCK__ && initialUser === undefined);

  const refresh = useCallback(async () => {
    if (__NEXEN_IS_MOCK__) return;
    const stored = __nexenGetToken();
    if (stored) setTok(stored);
    const me = await __nexenFetchMe(stored);
    if (me === null) {
      __nexenClearToken();
      setTok(null);
      setUser(null);
    } else if (me) {
      setUser(me);
    }
  }, []);

  useEffect(() => {
    if (__NEXEN_IS_MOCK__) return;
    __nexenGuardSignedOut();
    let alive = true;
    const stored = __nexenGetToken();
    if (stored) setTok(stored);
    // The server already said nobody is signed in, and there is no token to try:
    // asking again only logged a 401 on every signed-out page (2026-11-02).
    if (!stored && initialUser === null) {
      setLoading(false);
      return;
    }
    // The server already told us who this is (initialUser): fill in what the
    // session cookie does not carry (the name), without making the page wait.
    __nexenFetchMe(stored).then((me) => {
      if (!alive) return;
      if (me === null) {
        __nexenClearToken();
        setTok(null);
        setUser(null);
      } else if (me) {
        setUser(me);
      }
      setLoading(false);
    });
    return () => { alive = false; };
  }, []);

  const login = useCallback((t: string, u?: AuthUser | null) => {
    __nexenSetToken(t);
    setTok(t);
    if (u) {
      setUser(u);
    } else {
      void __nexenFetchMe(t).then((me) => { if (me) setUser(me); });
    }
    setLoading(false);
  }, []);
  const logout = useCallback(() => {
    // Read before clearing: the server ends THIS person's sessions, and the IDE
    // preview carries no cookie, only this token (2026-11-02).
    const t = __nexenGetToken();
    __nexenClearToken();
    setTok(null);
    setUser(null);
    // End the server session too — clearing the browser alone left the httpOnly
    // cookie valid, so the next page load was signed in again.
    if (!__NEXEN_IS_MOCK__ && typeof window !== 'undefined') {
      void fetch('/api/auth/logout', {
        method: 'POST', credentials: 'include',
        ...(t ? { headers: { Authorization: `Bearer ${t}` } } : {}),
      }).catch(() => {});
    }
  }, []);
  const value: AuthState = {
    user,
    token,
    isAuthenticated: __NEXEN_IS_MOCK__ || !!user || !!token,
    loading,
    login,
    logout,
    refresh,
  };
  return createElement(AuthContext.Provider, { value }, children);
}

export function useAuth(): AuthState {
  const ctx = useContext(AuthContext);
  if (ctx) return ctx;
  // In mock mode, never crash a preview page that renders outside the provider.
  if (__NEXEN_IS_MOCK__) return MOCK_SESSION;
  throw new Error('useAuth must be used within an AuthProvider');
}

export default AuthProvider;
